static void mfb_task_pointer_release(MfbDraw *mfb) {
    vk_mem_span_capture_release(&mfb->task_buffer.native);
    free(mfb->task_buffer.mapped);
    free(mfb->task_effects);
    vk_exec_pointer_phase_cancel(&mfb->task_readback);
}

static VkExecGraphicsResult mfb_draw_prepare(VkExec *, VkExecGraphicsDraw *, int,
                                             RcRegistryPosition, VkExecGpaSampleScope **);
